python3 -c "
import yaml, json
with open('/home/ubuntu/.agent-ml-research-be-idea-gen-0515-2/projects/importance_margin_vla_compress/registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})
# Find all experiments on westd-38929 that are RUNNING or recently active
westd_exps = {}
for eid, e in exps.items():
    spec = e.get('spec', {}) or {}
    server = spec.get('server', '')
    if 'westd-38929' in str(server) or '38929' in str(server):
        if e.get('status') in ('RUNNING', 'ANALYZING', 'PREPARING'):
            westd_exps[eid] = {'status': e['status'], 'gpu': spec.get('gpu_id', spec.get('gpu', '?')), 'pid': spec.get('pid', '?'), 'conclusion': e.get('conclusion', '')}
print(json.dumps(westd_exps, indent=2, default=str))
print()
# Also find spatial eval experiments for reference command
for eid, e in exps.items():
    if 'spatial' in eid and 'pi05' in eid and e.get('status') == 'RUNNING':
        spec = e.get('spec', {}) or {}
        print(f'Running spatial ref: {eid}')
        print(f'  command: {spec.get(\"command\", \"N/A\")}')
        print(f'  server: {spec.get(\"server\", \"N/A\")}')
        print(f'  gpu: {spec.get(\"gpu_id\", spec.get(\"gpu\", \"?\"))}')
print()
# Find l2norm spatial preparing experiments
for eid, e in exps.items():
    if 'l2norm' in eid and 'spatial' in eid:
        spec = e.get('spec', {}) or {}
        print(f'{eid}: status={e.get(\"status\")}, conclusion={e.get(\"conclusion\", \"\")}, server={spec.get(\"server\",\"?\")}, gpu={spec.get(\"gpu_id\",\"?\")}, hyp={e.get(\"hypothesis\",\"N/A\")[:100]}')
" 2>&1

